import { useEffect, useState } from "react";
import { UserProps } from "../types";

export function useUsers() {
  const [users, setUsers] = useState<UserProps[]>([]);
  const [active, setActive] = useState(null);
  useEffect(() => {
    fetch("http://localhost:4000/users")
      .then((res) => res.json())
      .then(setUsers);
  }, []);
  return {
    users,
  };
}
